/**
 * Lỗi trả về cho ứng dụng. Thông điệp bằng tiếng Việt, hiển thị được cho người dùng.
 */
public enum LvhvError: Swift.Error {

    
    
    /**
     * Ngày dương không tồn tại (ví dụ 30/2).
     */
    case InvalidDate(message: String)
    
    /**
     * Ngoài phạm vi 2000–3000.
     */
    case OutOfRange(message: String)
    
    /**
     * Mã việc không có trong danh sách `activities_json()`.
     */
    case UnknownActivity(message: String)
    
    /**
     * Khoảng ngày sai (kết thúc trước bắt đầu, hoặc dài quá một năm).
     */
    case BadRange(message: String)
    
    /**
     * Chức năng chưa có trong bản dựng này.
     */
    case Unavailable(message: String)
    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLvhvError: FfiConverterRustBuffer {
    typealias SwiftType = LvhvError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LvhvError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidDate(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .OutOfRange(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .UnknownActivity(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .BadRange(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Unavailable(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LvhvError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .InvalidDate(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .OutOfRange(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .UnknownActivity(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .BadRange(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Unavailable(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))

        
        }
    }
}


